.grc-funnel { display: flex; flex-direction: column; gap: 0.4rem; }
.grc-funnel__row { display: grid; grid-template-columns: 130px 1fr 42px; align-items: center; gap: 0.5rem; font-size: 0.8rem; }
.grc-chain { display: flex; align-items: center; justify-content: center; gap: 0.5rem; flex-wrap: wrap; padding: 0.6rem; }
.grc-chain__node { display: flex; flex-direction: column; align-items: center; gap: 0.3rem; padding: 0.5rem 0.7rem; border-radius: 10px; font-size: 0.72rem; font-weight: 600;
 border: 1px solid rgb(var(--grc-border)); background: rgba(var(--grc-surface-raised), 0.6); }
.grc-chain__arrow { color: rgb(var(--grc-text-faint)); }

/* Issues table */
.grc-table { width: 100%; border-collapse: collapse; font-size: 0.8rem; }
.grc-table thead th { text-align: left; padding: 0.6rem 0.7rem; font-size: 0.68rem; text-transform: uppercase; letter-spacing: 0.3px;
 color: rgb(var(--grc-text-muted)); border-bottom: 1px solid rgb(var(--grc-border)); position: sticky; top: 0; background: rgba(var(--grc-surface), 0.95); }
.grc-table tbody td { padding: 0.6rem 0.7rem; border-bottom: 1px solid rgb(var(--grc-border)); vertical-align: middle; }
.grc-table tbody tr { cursor: pointer; transition: background 120ms ease; }
.grc-table tbody tr:hover { background: rgba(var(--grc-primary), 0.08); }
.grc-table__ai { color: rgb(var(--grc-ai)); display: inline-flex; gap: 0.35rem; align-items: center; }
.grc-exposure { font-weight: 700; }

/* Change feed */
.grc-feed { display: flex; flex-direction: column; }
.grc-feed__row { display: flex; gap: 0.7rem; padding: 0.55rem 0; position: relative; }
.grc-feed__icon { width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; flex-shrink: 0;
 background: rgba(var(--grc-surface-raised), 0.9); border: 1px solid rgb(var(--grc-border)); }
.grc-feed__txt { font-size: 0.82rem; }
.grc-feed__line { position: absolute; left: 15px; top: 36px; bottom: -8px; width: 1px; background: rgb(var(--grc-border)); }
.grc-toggle { display: inline-flex; border: 1px solid rgb(var(--grc-border)); border-radius: 999px; overflow: hidden; }
.grc-toggle button { background: transparent; border: none; padding: 0.3rem 0.7rem; font-size: 0.74rem; color: rgb(var(--grc-text-muted)); cursor: pointer; }
.grc-toggle button.is-active { background: rgb(var(--grc-primary)); color: #fff; }

/* BU performance */
.grc-bu-table td, .grc-bu-table th { padding: 0.55rem 0.7rem; }
.grc-bu-trend { display: inline-flex; }

/* Drawer */
.grc-drawer-overlay { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.5); z-index: 80; animation: grc-fade 160ms ease; }
.grc-drawer { position: fixed; top: 0; right: 0; bottom: 0; width: min(560px, 94vw); z-index: 81;
 background: rgb(var(--grc-surface)); border-left: 1px solid rgb(var(--grc-border)); box-shadow: var(--grc-shadow);
 display: flex; flex-direction: column; animation: grc-slide 220ms ease; }
.grc-drawer__head { padding: 1rem 1.1rem; border-bottom: 1px solid rgb(var(--grc-border)); display: flex; justify-content: space-between; gap: 0.6rem; align-items: flex-start; }
.grc-drawer__title { font-size: 1.05rem; font-weight: 800; }
.grc-drawer__body { padding: 1rem 1.1rem; overflow-y: auto; display: flex; flex-direction: column; gap: 0.9rem; }
.grc-drawer__foot { padding: 0.8rem 1.1rem; border-top: 1px solid rgb(var(--grc-border)); display: flex; flex-wrap: wrap; gap: 0.4rem; background: rgba(var(--grc-surface-2), 0.7); }
.grc-field { display: flex; flex-direction: column; gap: 2px; }
.grc-field__label { font-size: 0.66rem; text-transform: uppercase; letter-spacing: 0.4px; color: rgb(var(--grc-text-faint)); }
.grc-field__value { font-size: 0.84rem; }
.grc-fieldgrid { display: grid; grid-template-columns: 1fr 1fr; gap: 0.7rem; }
.grc-aiblock { border: 1px solid rgba(var(--grc-ai), 0.4); border-radius: 12px; padding: 0.8rem; background: rgba(var(--grc-ai), 0.08); display: flex; flex-direction: column; gap: 0.6rem; }
.grc-aiqa__q { font-weight: 700; font-size: 0.8rem; display: flex; gap: 0.4rem; align-items: center; color: rgb(var(--grc-ai)); }
.grc-aiqa__a { font-size: 0.8rem; color: rgb(var(--grc-text-muted)); margin: 0.15rem 0 0; line-height: 1.45; }
.grc-chips { display: flex; flex-wrap: wrap; gap: 0.35rem; }
.grc-chip { font-size: 0.72rem; padding: 0.2rem 0.5rem; border-radius: 8px; background: rgba(var(--grc-surface-raised), 0.8); border: 1px solid rgb(var(--grc-border)); display: inline-flex; gap: 0.3rem; align-items: center; }

/* AI side panel */
.grc-aipanel { width: 340px; flex-shrink: 0; border-left: 1px solid rgb(var(--grc-border)); background: rgba(var(--grc-surface), 0.75);
