.grc-aipanel--collapsed { width: 46px; }
.grc-aipanel__head { padding: 0.8rem; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid rgb(var(--grc-border)); }
.grc-aipanel__title { display: flex; align-items: center; gap: 0.4rem; font-weight: 800; font-size: 0.85rem; color: rgb(var(--grc-ai)); }
.grc-aipanel__body { padding: 0.8rem; overflow-y: auto; display: flex; flex-direction: column; gap: 0.7rem; }
.grc-insight { border-radius: 12px; padding: 0.7rem; border: 1px solid rgb(var(--grc-border)); background: rgba(var(--grc-surface-raised), 0.7); display: flex; flex-direction: column; gap: 0.4rem; }
.grc-insight--critical { border-left: 3px solid rgb(var(--grc-critical)); }
.grc-insight--high { border-left: 3px solid rgb(var(--grc-high)); }
.grc-insight--watch { border-left: 3px solid rgb(var(--grc-watch)); }
.grc-insight--info { border-left: 3px solid rgb(var(--grc-info)); }
.grc-insight__type { font-size: 0.64rem; font-weight: 800; letter-spacing: 0.5px; color: rgb(var(--grc-ai)); display: flex; align-items: center; gap: 0.3rem; }
.grc-insight__title { font-size: 0.82rem; font-weight: 600; line-height: 1.35; }
.grc-insight__reason { font-size: 0.74rem; color: rgb(var(--grc-text-muted)); }
.grc-insight__foot { display: flex; align-items: center; justify-content: space-between; gap: 0.4rem; }
.grc-insight__actions { display: flex; gap: 0.3rem; flex-wrap: wrap; }
.grc-collapsed-rail { display: flex; flex-direction: column; align-items: center; gap: 0.8rem; padding-top: 0.8rem; }

/* Floating AI */
.grc-fab { position: fixed; right: 1.2rem; bottom: 1.2rem; z-index: 70; width: 56px; height: 56px; border-radius: 50%;
 border: none; cursor: pointer; display: grid; place-items: center; color: #fff;
 background: linear-gradient(135deg, rgb(var(--grc-ai)), rgb(var(--grc-primary))); box-shadow: var(--grc-shadow); }
.grc-fab:hover { transform: scale(1.05); }
.grc-chatwin { position: fixed; right: 1.2rem; bottom: 5.2rem; z-index: 71; width: min(380px, 92vw); max-height: 70vh;
 background: rgb(var(--grc-surface)); border: 1px solid rgba(var(--grc-ai), 0.4); border-radius: 16px; box-shadow: var(--grc-shadow);
 display: flex; flex-direction: column; overflow: hidden; animation: grc-slideup 200ms ease; }
.grc-chatwin__head { padding: 0.8rem; background: linear-gradient(135deg, rgba(var(--grc-ai), 0.2), rgba(var(--grc-primary), 0.12)); display: flex; justify-content: space-between; align-items: center; }
.grc-chatwin__title { font-weight: 800; font-size: 0.9rem; display: flex; align-items: center; gap: 0.4rem; }
.grc-chatwin__body { padding: 0.8rem; overflow-y: auto; display: flex; flex-direction: column; gap: 0.6rem; }
.grc-chatwin__hint { font-size: 0.76rem; color: rgb(var(--grc-text-muted)); }
.grc-suggest { display: flex; flex-direction: column; gap: 0.35rem; }
.grc-suggest button { text-align: left; background: rgba(var(--grc-surface-raised), 0.8); border: 1px solid rgb(var(--grc-border)); border-radius: 10px;
 padding: 0.5rem 0.6rem; font-size: 0.78rem; color: rgb(var(--grc-text)); cursor: pointer; }
.grc-suggest button:hover { border-color: rgba(var(--grc-ai), 0.6); background: rgba(var(--grc-ai), 0.1); }
.grc-msg { font-size: 0.8rem; padding: 0.5rem 0.65rem; border-radius: 10px; line-height: 1.4; }
.grc-msg--user { align-self: flex-end; background: rgb(var(--grc-primary)); color: #fff; }
.grc-msg--ai { align-self: flex-start; background: rgba(var(--grc-ai), 0.12); border: 1px solid rgba(var(--grc-ai), 0.35); }

/* Placeholder tab */
.grc-placeholder { display: flex; flex-direction: column; gap: 0.5rem; }

@keyframes grc-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes grc-slide { from { transform: translateX(40px); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
@keyframes grc-slideup { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }

/* Responsive */
@media (max-width: 1440px) {
 .grc-hero { grid-template-columns: 1fr 1fr; }
 .grc-hero__attn { grid-column: 1 / -1; }
 .grc-kpis { grid-template-columns: repeat(4, 1fr); }
 .grc-pulse { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 1100px) {
 .grc-hero, .grc-landscape, .grc-two, .grc-assurance { grid-template-columns: 1fr; }
 .grc-kpis { grid-template-columns: repeat(2, 1fr); }
 .grc-timeline { grid-template-columns: 1fr; }
 .grc-aipanel { display: none; }
}
@media (max-width: 720px) {
 .grc-kpis, .grc-pulse { grid-template-columns: 1fr; }
 .grc-header__center { display: none; }
}
