","import React, { createContext, useContext, useState, useCallback, useMemo } from "react";
import { DEFAULT_SELECTORS, GlobalSelectors } from "../data/mockData";

interface AppCtx {
 selectors: GlobalSelectors;
 setSelector: (key: keyof GlobalSelectors, value: string) => void;
 aiPanelOpen: boolean;
 setAiPanelOpen: (v: boolean) => void;
 scale: (n: number) => number;
 buFocused: boolean;
}

const AppContext = createContext<AppCtx>({
 selectors: DEFAULT_SELECTORS,
 setSelector: () => {},
 aiPanelOpen: true,
 setAiPanelOpen: () => {},
 scale: n => n,
 buFocused: false
});

// Deterministic per-BU multiplier so selecting a Business Unit visibly
// changes the mock figures across the page.
const BU_FACTOR: Record<string, number> = {
 "All Business Units": 1,
 Finance: 1.18,
 Operations: 1.26,
 Procurement: 1.12,
 Technology: 0.84,
 HR: 0.7,
 Corporate: 0.78
};

export function AppProvider({ children }: { children: React.ReactNode }) {
 const [selectors, setSelectors] = useState<GlobalSelectors>(DEFAULT_SELECTORS);
 const [aiPanelOpen, setAiPanelOpen] = useState(true);

 const setSelector = useCallback((key: keyof GlobalSelectors, value: string) => {
 setSelectors(prev => ({ ...prev, [key]: value }));
 }, []);

 const factor = BU_FACTOR[selectors.businessUnit] ?? 1;
 const buFocused = selectors.businessUnit !== "All Business Units";

 const scale = useCallback(
 (n: number) => Math.round(n * factor),
 [factor]
 );

 const value = useMemo(
 () => ({ selectors, setSelector, aiPanelOpen, setAiPanelOpen, scale, buFocused }),
 [selectors, setSelector, aiPanelOpen, scale, buFocused]
 );

 return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
}

export const useApp = () => useContext(AppContext);
","import React, { createContext, useContext, useEffect, useState, useCallback } from "react";

type Theme = "light" | "dark";
const STORAGE_KEY = "grc_vp_theme";

interface ThemeCtx {
 theme: Theme;
 toggle: () => void;
}

const ThemeContext = createContext<ThemeCtx>({ theme: "dark", toggle: () => {} });

function readInitial(): Theme {
 try {
 const stored = window.localStorage.getItem(STORAGE_KEY);
 if (stored === "light" || stored === "dark") return stored;
 } catch (e) {
 /* ignore */
 }
 return "dark";
}

function applyThemeClass(theme: Theme) {
 const root = document.documentElement;
 root.classList.remove("grc-theme-light", "grc-theme-dark");
 root.classList.add(theme === "dark" ? "grc-theme-dark" : "grc-theme-light");
}

export function ThemeProvider({ children }: { children: React.ReactNode }) {
 const [theme, setTheme] = useState<Theme>(readInitial);

 useEffect(() => {
 applyThemeClass(theme);
 try {
 window.localStorage.setItem(STORAGE_KEY, theme);
 } catch (e) {
 /* ignore */
 }
 }, [theme]);

 const toggle = useCallback(() => {
 setTheme(prev => (prev === "dark" ? "light" : "dark"));
 }, []);

 return <ThemeContext.Provider value={{ theme, toggle }}>{children}</ThemeContext.Provider>;
}

export const useTheme = () => useContext(ThemeContext);
