import { ASSURANCE_ROWS, ASSURANCE_SUMMARY } from "../../data/content";

const CELL_LABEL: Record<string, string> = { covered: "Covered", partial: "Partial", gap: "Gap", planned: "Planned" };
const CELL_ICON: Record<string, string> = { covered: "circle-check-outline", partial: "circle-half-outline", gap: "triangle-exclamation-outline", planned: "calendar-clock-outline" };

function Cell({ state }: { state: string }) {
 return <span className={`grc-cell grc-cell--${state}`}><Icon icon={CELL_ICON[state] as any} size="sm" />{CELL_LABEL[state]}</span>;
}

export function CombinedAssurance() {
 const { run } = useActions();
 return (
 <section className="grc-section">
 <SectionHead icon="venn-intersection-outline" title="Combined Assurance" hint="Do we have sufficient assurance over our highest risks?" />
 <div className="grc-assurance">
 <Card title="Three Lines Assurance Matrix" icon="table-outline" pad0>
 <div style={{ padding: "0.4rem 0.8rem 0.8rem" }}>
 <table className="grc-matrix">
 <thead>
 <tr>
 <th>Top Enterprise Risk</th>
 <th>1st Line<br /><small>Business/Control Owners</small></th>
 <th>2nd Line<br /><small>Risk/Compliance</small></th>
 <th>3rd Line<br /><small>Internal Audit</small></th>
 </tr>
 </thead>
 <tbody>
 {ASSURANCE_ROWS.map(r => (
 <tr key={r.risk}>
 <td>{r.risk}</td>
 <td><Cell state={r.line1} /></td>
 <td><Cell state={r.line2} /></td>
 <td><Cell state={r.line3} /></td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 </Card>

 <div className="grc-assurance__side">
 <Card>
 <div className="grc-bigmetric">
 <ProgressRing value={ASSURANCE_SUMMARY.coverage} severity="healthy" size={110} />
 <div className="grc-bigmetric__label">Assurance Coverage</div>
 </div>
