 <div className="grc-statgrid">
 <Metric label="Critical Gaps" value={ASSURANCE_SUMMARY.gaps} />
 <Metric label="Duplicate Activities" value={ASSURANCE_SUMMARY.duplicates} />
 <Metric label="Unassured High Risks" value={ASSURANCE_SUMMARY.unassured} />
 </div>
 <div className="grc-ailine">
 <Icon icon="ai-sparkle-fill" size="sm" />
 <span>{ASSURANCE_SUMMARY.aiInsight}</span>
