export function TabView({ tab, onOpenIssue, onSelectRisk }: { tab: string; onOpenIssue: (id: string) => void; onSelectRisk: (r: RiskBubble) => void }) {
 const meta = TABS.find(t => t.id === tab);
 switch (tab) {
 case "risk":
 return (
 <section className="grc-section">
 <SectionHead icon={meta?.icon} title={meta?.label || "Enterprise Risk"} hint="Risk posture, appetite, and early-warning signals" />
 <StatRow tab="risk" />
 <RiskLandscape onSelectRisk={onSelectRisk} />
 <TopIssues onOpenIssue={onOpenIssue} />
 <BusinessUnits />
 </section>
 );
 case "controls":
 return (
 <section className="grc-section">
 <SectionHead icon={meta?.icon} title={meta?.label || "Internal Controls"} hint="Control effectiveness, failures, and remediation" />
 <StatRow tab="controls" />
 <ControlRemediation />
 <TopIssues onOpenIssue={onOpenIssue} />
 </section>
 );
 case "regulatory":
 return (
 <section className="grc-section">
 <SectionHead icon={meta?.icon} title={meta?.label || "Regulatory Compliance"} hint="Obligations, changes, and compliance actions" />
 <StatRow tab="regulatory" />
 <RegulatoryIntel />
 <TopIssues onOpenIssue={onOpenIssue} />
 </section>
 );
 case "governance":
 return (
 <section className="grc-section">
 <SectionHead icon={meta?.icon} title={meta?.label || "Governance & Policy"} hint="Policy lifecycle and delegation of authority" />
 <StatRow tab="governance" />
 <PolicyGovernance />
 <ChangeFeed />
 </section>
 );
 case "internal":
 return <InternalComplianceView onOpenIssue={onOpenIssue} />;
 case "assurance":
 return (
 <section className="grc-section">
 <SectionHead icon={meta?.icon} title={meta?.label || "Combined Assurance"} hint="Three lines coverage over the highest risks" />
 <CombinedAssurance />
 <BusinessUnits />
 </section>
 );
 case "ai":
 return <AiTabView />;
 default:
 return null;
 }
}
