const ACTIONS = [
 "Assign Owner", "Escalate", "Request Assessment", "Create Remediation",
 "Accept Recommendation", "Dismiss Recommendation", "Ask AI"
];

export function IssueDrawer({ issueId, onClose }: { issueId: string; onClose: () => void }) {
 const { run } = useActions();
 const issue = ISSUES.find(i => i.id === issueId);

 useEffect(() => {
 const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
 document.addEventListener("keydown", onKey);
 return () => document.removeEventListener("keydown", onKey);
 }, [onClose]);

 if (!issue) return null;
 const sev = issue.priority === "CRITICAL" ? "critical" : "high";

 return (
 <>
 <div className="grc-drawer-overlay" onClick={onClose} />
 <aside className="grc-drawer" role="dialog" aria-label="Executive issue detail">
 <div className="grc-drawer__head">
 <div>
 <div className="grc-drawer__title">{issue.issue}</div>
 <div style={{ marginTop: 6, display: "flex", gap: 6, flexWrap: "wrap" }}>
 <StatusPill severity={sev} label={issue.priority} size="sm" />
 <StatusPill severity={issue.status === "Overdue" ? "critical" : "watch"} label={issue.status} size="sm" />
 </div>
 </div>
 <button className="grc-iconbtn" aria-label="Close" onClick={onClose}><Icon icon="close-outline" size="md" /></button>
 </div>

 <div className="grc-drawer__body">
 <Field label="Executive Summary" value={issue.summary} />
 <Field label="Why This Matters" value={issue.whyMatters} />
 <div className="grc-fieldgrid">
 <Field label="Business Impact" value={issue.businessImpact} />
 <Field label="Financial Exposure" value={<span className="grc-exposure">{issue.exposure}</span>} />
 <Field label="Business Unit" value={issue.bu} />
 <Field label="Owner" value={issue.owner} />
 <Field label="Affected Risk" value={issue.affectedRisk} />
 <Field label="Regulatory Impact" value={issue.regulatoryImpact} />
 </div>
 <Field label="Affected Controls" value={issue.affectedControls} />
 <Field label="Affected Policies" value={issue.affectedPolicies} />
 <Field label="Root Cause" value={issue.rootCause} />
 <div className="grc-fieldgrid">
 <Field label="Current Remediation" value={issue.remediation} />
 <Field label="Due Date" value={issue.dueDate} />
 </div>
 <div className="grc-field">
 <span className="grc-field__label">Related Evidence</span>
 <div className="grc-chips">
 {issue.evidence.map(e => <span className="grc-chip" key={e}><Icon icon="paperclip-outline" size="sm" />{e}</span>)}
 </div>
 </div>

 <div className="grc-aiblock">
 <span className="grc-aibrief__tag"><Icon icon="ai-sparkle-fill" size="sm" /> AI ANALYSIS</span>
 {issue.aiAnalysis.map((qa, i) => (
 <div key={i}>
 <div className="grc-aiqa__q"><Icon icon="circle-question-outline" size="sm" />{qa.q}</div>
 <p className="grc-aiqa__a">{qa.a}</p>
 </div>
 ))}
 </div>
 </div>

 <div className="grc-drawer__foot">
 {ACTIONS.map(a => (
 <Button key={a} label={a} size="sm"
 variant={a === "Accept Recommendation" ? "primary" : a === "Escalate" ? "primary-negative" : a === "Dismiss Recommendation" ? "tertiary" : "secondary"}
 onClicked={() => run(a, `Mock action: "${a}" for issue "${issue.issue}".`)} />
 ))}
 </div>
 </aside>
 </>
 );
}
