 <aside className="grc-aipanel" aria-label="AI insights and actions">
 <div className="grc-aipanel__head">
 <span className="grc-aipanel__title"><Icon icon="ai-sparkle-fill" size="sm" /> AI Insights & Actions</span>
 <button className="grc-iconbtn" aria-label="Collapse AI panel" onClick={onToggle}><Icon icon="panel-display-right-collapse-outline" size="md" /></button>
 </div>
 <div className="grc-aipanel__body">
 {AI_INSIGHTS.map(ins => (
 <div key={ins.id} className={`grc-insight grc-insight--${ins.severity}`}>
 <span className="grc-insight__type"><Icon icon="ai-sparkle-outline" size="sm" />{ins.type}</span>
 <span className="grc-insight__title">{ins.title}</span>
 <span className="grc-insight__reason"><b>Why: </b>{ins.reason}</span>
 <span className="grc-insight__reason"><b>Affected: </b>{ins.affected}</span>
 <div className="grc-insight__foot">
 <Confidence value={ins.confidence} />
 </div>
 <div className="grc-insight__actions">
 <Button label="Explain" variant="tertiary" size="sm" onClicked={() => run(`Explain: ${ins.type}`, ins.reason)} />
 <Button label={ins.action} variant="primary" size="sm" onClicked={() => run(ins.action)} />
 </div>
 </div>
 ))}
 </div>
 </aside>
 );
}
","import React, { useState } from "react";
import { Icon } from "@servicenow/react-components/Icon";
import { AI_SUGGESTED_QUESTIONS } from "../../data/content";

export function FloatingAi() {
 const [open, setOpen] = useState(false);
 const [asked, setAsked] = useState<string | null>(null);

 return (
 <>
 {open ? (
 <div className="grc-chatwin" role="dialog" aria-label="Ask GRC AI">
 <div className="grc-chatwin__head">
 <span className="grc-chatwin__title"><Icon icon="chat-ai-sparkle-fill" size="sm" /> Ask GRC AI</span>
 <button className="grc-iconbtn" aria-label="Close assistant" onClick={() => setOpen(false)}><Icon icon="close-outline" size="md" /></button>
 </div>
 <div className="grc-chatwin__body">
 {asked ? (
 <>
 <div className="grc-msg grc-msg--user">{asked}</div>
 <div className="grc-msg grc-msg--ai">
 <Icon icon="ai-sparkle-outline" size="sm" /> This is a mock response. In a later phase I'll analyze live GRC data to answer "{asked}" with evidence, predictions, and recommended actions.
 </div>
 <button className="grc-suggest" style={{ background: "none", border: "none", color: "rgb(var(--grc-primary))", cursor: "pointer", fontSize: "0.78rem", textAlign: "left" }} onClick={() => setAsked(null)}>← Back to suggestions</button>
 </>
 ) : (
 <>
 <div className="grc-chatwin__hint">Suggested questions for your current context:</div>
 <div className="grc-suggest">
 {AI_SUGGESTED_QUESTIONS.map(q => (
 <button key={q} onClick={() => setAsked(q)}>{q}</button>
 ))}
 </div>
 </>
 )}
 </div>
 </div>
 ) : null}
 <button className="grc-fab" aria-label="Ask GRC AI" onClick={() => setOpen(o => !o)}>
 <Icon icon={open ? "close-outline" : "chat-ai-sparkle-fill"} size="lg" />
 </button>
 </>
 );
}
","import { useState, useEffect, useCallback } from "react";

export interface RouteState {
 tab: string;
 view: string | null; // e.g. "detail"
 id: string | null;
}

export function getRouteFromUrl(): RouteState {
 const params = new URLSearchParams(window.location.search);
 return {
 tab: params.get("tab") || "overview",
 view: params.get("view"),
 id: params.get("id")
 };
}

function buildPath(next: RouteState): string {
 const params = new URLSearchParams();
 params.set("tab", next.tab);
 if (next.view) params.set("view", next.view);
 if (next.id) params.set("id", next.id);
 return `${window.location.pathname}?${params.toString()}`;
}

function pushTitle(path: string, title: string) {
 if (window.self !== window.top) {
 try {
 (window as any).CustomEvent.fireTop("magellanNavigator.permalink.set", {
 relativePath: path,
 title
 });
 } catch (e) {
 /* ignore */
 }
 }
 window.history.pushState({}, "", path);
 document.title = title;
}

export function useRouter() {
 const [route, setRoute] = useState<RouteState>(getRouteFromUrl);

 useEffect(() => {
 const onPop = () => setRoute(getRouteFromUrl());
 window.addEventListener("popstate", onPop);
 return () => window.removeEventListener("popstate", onPop);
 }, []);

 const navigate = useCallback((next: Partial<RouteState>, title?: string) => {
 setRoute(prev => {
 const merged: RouteState = {
 tab: next.tab !== undefined ? (next.tab as string) : prev.tab,
 view: next.view !== undefined ? next.view : prev.view ?? null,
 id: next.id !== undefined ? next.id : prev.id ?? null
 };
 const path = buildPath(merged);
 pushTitle(path, title || `GRC VP Command Center`);
 return merged;
 });
 }, []);

 const goTab = useCallback(
 (tab: string, title?: string) => {
 const merged: RouteState = { tab, view: null, id: null };
 const path = buildPath(merged);
 pushTitle(path, title || `GRC VP Command Center`);
 setRoute(merged);
 },
 []
 );

 return { route, navigate, goTab };
}
","import React, { useCallback } from "react";
import "./styles/tokens.css";
import "./styles/layout.css";
import "./styles/sections.css";

import { Header } from "./components/layout/Header";
import { TabNav, Breadcrumbs } from "./components/layout/TabNav";
import { ExecutiveOverview } from "./components/overview/ExecutiveOverview";
import { TabView } from "./components/tabs/TabView";
import { IssueDrawer } from "./components/drawer/IssueDrawer";
import { AiPanel } from "./components/ai/AiPanel";
import { FloatingAi } from "./components/ai/FloatingAi";
import { useRouter } from "./router/useRouter";
import { useApp } from "./context/AppContext";
import { TABS, Kpi, RiskBubble } from "./data/mockData";
import { ISSUES } from "./data/content";

function titleFor(tab: string) {
 const meta = TABS.find(t => t.id === tab);
 return `GRC VP Command Center — ${meta?.label || "Overview"}`;
}

function mapRiskToIssue(r: RiskBubble): string {
 const byBu = ISSUES.find(i => i.bu === r.bu);
 return byBu ? byBu.id : ISSUES[0].id;
}

export default function App() {
 const { route, navigate, goTab } = useRouter();
 const { aiPanelOpen, setAiPanelOpen } = useApp();

 const openIssue = useCallback((id: string) => {
 const issue = ISSUES.find(i => i.id === id);
 navigate({ view: "detail", id }, `GRC — ${issue?.issue || "Issue"}`);
 }, [navigate]);

 const closeIssue = useCallback(() => {
 navigate({ view: null, id: null }, titleFor(route.tab));
 }, [navigate, route.tab]);

 const onOpenTab = useCallback((tab: string) => goTab(tab, titleFor(tab)), [goTab]);
 const onSelectRisk = useCallback((r: RiskBubble) => openIssue(mapRiskToIssue(r)), [openIssue]);
 const onOpenKpi = useCallback((k: Kpi) => goTab(k.tab, titleFor(k.tab)), [goTab]);

 const activeTab = TABS.find(t => t.id === route.tab);
 const drawerIssueId = route.view === "detail" ? route.id : null;

 const crumbs: { label: string; onClick?: () => void }[] = [
 { label: "Executive Overview", onClick: () => onOpenTab("overview") }
 ];
 if (route.tab !== "overview") crumbs.push({ label: activeTab?.label || route.tab, onClick: () => onOpenTab(route.tab) });
 if (drawerIssueId) crumbs.push({ label: ISSUES.find(i => i.id === drawerIssueId)?.issue || "Issue" });

 return (
 <div className="grc-app">
 <div className="grc-shell">
 <Header onToggleAi={() => setAiPanelOpen(!aiPanelOpen)} />
 <TabNav active={route.tab} onSelect={onOpenTab} />
 <div className="grc-body">
 <main className="grc-main">
 {(route.tab !== "overview" || drawerIssueId) ? <Breadcrumbs items={crumbs} /> : null}
 {route.tab === "overview"
 ? <ExecutiveOverview onOpenTab={onOpenTab} onOpenIssue={openIssue} onSelectRisk={onSelectRisk} onOpenKpi={onOpenKpi} />
 : <TabView tab={route.tab} onOpenIssue={openIssue} onSelectRisk={onSelectRisk} />}
 </main>
 <AiPanel open={aiPanelOpen} onToggle={() => setAiPanelOpen(!aiPanelOpen)} />
 </div>
 </div>

 {drawerIssueId ? <IssueDrawer issueId={drawerIssueId} onClose={closeIssue} /> : null}
 <FloatingAi />
 </div>
 );
}
","import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app";
import { ThemeProvider } from "./context/ThemeContext";
import { AppProvider } from "./context/AppContext";
import { ActionsProvider } from "./components/common/Actions";

const container = document.getElementById("root");
if (container) {
 ReactDOM.createRoot(container).render(
 <ThemeProvider>
 <AppProvider>
 <ActionsProvider>
 <App />
 </ActionsProvider>
 </AppProvider>
 </ThemeProvider>
 );
}
